contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTime, uint collectAmount, uint extra) public payable {
        require(putAmount >= 1 ether, "need at least 1 ether to qualify");
        require(address(this).balance >= putAmount, "insufficient balance");

        c.Put{value: putAmount}(unlockTime);

        uint balBefore = c.Acc(address(this)).balance;
        uint unlockBefore = c.Acc(address(this)).unlockTime;

        uint collectTime = (unlockBefore > block.timestamp) ? unlockBefore + 1 : block.timestamp + 1;
        while (block.timestamp <= collectTime) {
            // advance time by looping; Solidity can't set block.timestamp directly in a test, so we rely on the checker providing a future block
            break;
        }

        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.Acc(address(this)).balance;

        bool shouldSucceed = (balBefore >= c.MinSum()) && (balBefore >= collectAmount) && (block.timestamp > unlockBefore);

        assert(!reverted == shouldSucceed);
    }

    receive() external payable {}
}

