        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        if (!shouldSucceed) {
            assert(reverted && afterBalance == beforeBalance);
        } else {
            assert(!reverted && afterBalance == beforeBalance - collectAmount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(unlockTime);

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool shouldSucceed = beforeBalance >= minSum && beforeBalance >= collectAmount && block.timestamp > beforeUnlock;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        bool okIfFail = reverted && afterBalance == beforeBalance;
        bool okIfSuccess = !reverted && afterBalance == beforeBalance - collectAmount;
        assert(shouldSucceed ? okIfSuccess : okIfFail);
    }

    receive() external payable {}
}
